def fn(x, vocab):
    flat = x.reshape(-1).long()
    return (flat.unsqueeze(1) == torch.arange(int(vocab), device=x.device)).to(torch.float32)

def fn(x, vocab):
    flat = x.reshape(-1).long()
    return (flat.unsqueeze(0).unsqueeze(2) == torch.arange(int(vocab), device=x.device)).to(torch.float32)
